'use strict';
const PCR = (() => {
  const titles={acks:'Commentaires à acquitter',scan:'À scanner',expected:'Non réceptionnés',waiting:'Réceptionnés sans résultat',done:'Réceptionnés avec résultat',scanned:'Échantillons scannés',requests:'Tous les dossiers',cancelled:'Échantillons annulés',errors:'Échantillons en erreur'};
  const state={data:null,filter:'scan',search:'',site:'',from:defaultFrom(),to:'',group:'',order:'date',patient:'',notice:null,failed:[],queue:[],draining:false,timer:null,preview:null,pending:null,confirming:null,mailing:false,mailSel:new Set(),mails:[]};
  function stop(){clearTimeout(state.timer);state.timer=null;}
  function defaultFrom(){const d=new Date();d.setDate(d.getDate()-14);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
  function reset(){stop();Object.assign(state,{data:null,notice:null,failed:[],queue:[],preview:null,pending:null,confirming:null,search:'',site:'',from:defaultFrom(),to:'',group:'',order:'date',patient:'',filter:'scan',mailing:false,mailSel:new Set(),mails:[]});}
  // Optional per-analysis delays, measured in the browser: SIL/middleware times are local, scans are UTC.
  // Days without reception (Sundays, French public holidays, exceptional dates) do not count.
  const HOLIDAY_LABELS={jan1:'1er janvier',easter_mon:'Lundi de Pâques',may1:'1er mai',may8:'8 mai',ascension:'Ascension',pentecost_mon:'Lundi de Pentecôte',jul14:'14 juillet',aug15:'15 août',nov1:'1er novembre',nov11:'11 novembre',dec25:'25 décembre'};
  const WEEKDAYS=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];
  const holidayCache=new Map();
  function isoDay(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
  function holidays(year){
    if(holidayCache.has(year))return holidayCache.get(year);
    // Easter Sunday (Meeus/Jones/Butcher, Gregorian calendar).
    const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31),day=((h+l-7*m+114)%31)+1;
    const plus=n=>isoDay(new Date(year,month-1,day+n));
    const list={jan1:`${year}-01-01`,easter_mon:plus(1),may1:`${year}-05-01`,may8:`${year}-05-08`,ascension:plus(39),pentecost_mon:plus(50),jul14:`${year}-07-14`,aug15:`${year}-08-15`,nov1:`${year}-11-01`,nov11:`${year}-11-11`,dec25:`${year}-12-25`};
    holidayCache.set(year,list);return list;
  }
  function closedConfig(){return state.data?.config?.closed_days||{weekdays:[6],holidays_off:[],extra_dates:[]};}
  function isClosed(d,c=closedConfig()){const iso=isoDay(d),wd=(d.getDay()+6)%7;if(c.weekdays.includes(wd)||c.extra_dates.includes(iso))return true;const h=holidays(d.getFullYear());return Object.entries(h).some(([k,v])=>v===iso&&!c.holidays_off.includes(k));}
  function openHours(start,end){
    // Hours between start and end, counting only days with reception (local time).
    let total=0,cursor=new Date(start),guard=0;const c=closedConfig();
    while(cursor<end&&guard++<800){const next=new Date(cursor.getFullYear(),cursor.getMonth(),cursor.getDate()+1);const stop=next<end?next:end;if(!isClosed(cursor,c))total+=stop-cursor;cursor=next;}
    return total/3600000;
  }
  function overdue(since,hours){const t=Date.parse(since||'');if(!hours||isNaN(t))return 0;const h=openHours(new Date(t),new Date())-hours;return h>0?h:0;}
  function closedText(){const c=closedConfig(),days=c.weekdays.map(d=>WEEKDAYS[d].toLowerCase());return 'hors '+[...days,'jours fériés'].join(', ').replace(/, ([^,]*)$/,' et $1');}
  function alertOn(kind){const a=state.data?.config?.delay_alerts;return a?a[kind]===true:kind==='receipt';}
  function receiptLate(p){return alertOn('receipt')&&p.state==='attendu'&&!p.receipt&&p.request_code?overdue(p.requested_at,p.receipt_delay_hours):0;}
  function resultLate(p){return alertOn('result')&&p.state==='attendu'&&p.receipt&&!p.analysis_done&&p.request_code?overdue(p.receipt.at,p.result_delay_hours):0;}
  function lateText(h){return h<48?Math.ceil(h)+' h':Math.floor(h/24)+' j';}
  // Two distinct signals: tube not yet received (amber, hourglass) / received tube without result (crimson, flask).
  function lateChip(h,kind){if(!h)return '';const receipt=kind==='receipt';return `<span class="pcr-late ${receipt?'pcr-late-receipt':'pcr-late-result'}" title="${esc((receipt?'Tube non reçu : retard de réception':'Tube reçu sans résultat : délai de résultat')+' dépassé de '+lateText(h)+' ('+closedText()+')')}">${receipt?'⧗ NON REÇU':'⚗ SANS RÉSULTAT'} +${esc(lateText(h))}</span> `;}
  function clock(iso){const d=new Date(iso);return isNaN(d)?'':d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});}
  function stamp(iso){const d=new Date(iso);if(isNaN(d))return '';const t=clock(iso);return d.toDateString()===new Date().toDateString()?t:d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'})+' '+t;}
  function ordinal(n){return n===1?'1er':n+'e';}
  function scanTimes(scans){return (scans||[]).map((s,i,a)=>`${ordinal(i+1)} scan ${dateLabel(s.at)} · ${s.actor}${i===a.length-1?' (actuel)':''}`);}
  function personName(p){return String(p.patient||p.patient_id||'Patient non transmis').replaceAll('^',' ').replace(/\s+/g,' ').trim();}
  function pendingScans(){return state.draining||state.queue.length>0;}
  function brand(){return `<a href="/" class="brand-home brand-compact" data-action="pcr-home" aria-label="PCRLia — Accueil"><div class="brand-lockup"><img src="/brand.svg" alt="" width="38" height="38"><div class="brand">PCRLia</div></div><div class="brand-endorsement"><small>UNE INTERFACE ${brandSignature()}</small>${labLogo(200)}</div></a>`;}
  function groupName(id){return state.data?.groups.find(g=>g.id===id)?.label||'Autres PCR';}
  function patientKey(p){return p.patient_id?'patient:'+p.patient_id:p.dossier?'dossier:'+p.dossier:'sample:'+p.sample_id;}
  function inView(p,view=state.filter){
    const received=!!(p.request_code&&p.state==='attendu'&&p.receipt);
    return view==='acks'?(p.comments||[]).some(c=>c.to_ack&&!c.ack):view==='errors'?p.issues?.some(i=>['error','duplicate'].includes(i.kind)):view==='expected'?p.status==='expected':view==='done'?received&&!!p.analysis_done:view==='waiting'?received&&!p.analysis_done&&!!p.done_code:view==='scan'||view==='scanned'?!!p.scanned_at:view==='requests'?p.state!=='unmatched':p.state==='annule';}
  function needsAction(p,view){return view==='errors'?p.pending_error:view==='cancelled'?p.state==='annule'&&p.pending_issues?.some(i=>i.key==='cancelled:'+p.request_code):inView(p,view);}
  function displayText(value){return String(value||'').replaceAll('TUBES EN ERREUR','ÉCHANTILLONS EN ERREUR').replaceAll('Demande non transmise','Analyse non transmise').replaceAll('Absent des demandes','Aucune analyse reçue').replaceAll('Demande annulée','Analyse annulée').replaceAll('Demande ou paramétrage actualisé','Analyse ou paramétrage actualisé').replaceAll('Code de demande','Code automate').replaceAll('code de demande','code automate');}
  function errorReasons(p){return [...new Set((p.issues||[]).filter(i=>['error','duplicate'].includes(i.kind)).map(i=>displayText(i.label)))].join(' · ');}
  // Dossier date, or scan date for a tube received before its analyses.
  function filterDay(p){return p.date_demande||(p.scanned_at?.at||p.receipt?.at||'').slice(0,10);}
  function matchesFilters(p){return (!state.site||p.site===state.site)&&(!state.group||p.group===state.group)&&(!state.patient||patientKey(p)===state.patient)&&(!state.from||filterDay(p)>=state.from)&&(!state.to||filterDay(p)&&filterDay(p)<=state.to)&&(!state.search||[p.patient,p.patient_id,p.sample_id,p.dossier,p.request_code,p.label,p.site,p.lab_detail,p.lab_code,...(p.error_reasons||[]),...(p.comments||[]).map(c=>c.text)].join(' ').toLocaleLowerCase('fr').includes(state.search.toLocaleLowerCase('fr')));}
  function filtered(){return (state.data?.pairs||[]).filter(p=>inView(p)&&(state.filter==='scan'||matchesFilters(p)));}
  function selectionCounts(pairs){const orders=pairs.filter(p=>p.request_code),known=orders.filter(p=>p.dossier);return {requests:new Set(known.map(p=>p.dossier)).size,samples:new Set(pairs.map(p=>p.sample_id)).size,withoutDossier:new Set(orders.filter(p=>!p.dossier).map(p=>p.sample_id)).size};}
  function countLabel(n,singular,plural=singular+'s'){return n+' '+(n===1?singular:plural);}
  function navCount(id){
    const all=state.data?.pairs||[],global=['errors','cancelled'].includes(id);
    const pairs=all.filter(p=>global?needsAction(p,id):inView(p,id)&&(state.filter==='scan'||matchesFilters(p)));
    const counts=selectionCounts(pairs),late=new Set(pairs.filter(p=>id==='expected'?receiptLate(p):id==='waiting'?resultLate(p):0).map(p=>p.sample_id)).size;
    return {value:id==='requests'?counts.requests:counts.samples,dossiers:counts.requests,late,title:global?'Échantillons nécessitant encore une action, tous filtres confondus':'Échantillons et dossiers distincts dans la sélection'};
  }
  function shortDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.slice(8,10)+'/'+value.slice(5,7)+'/'+value.slice(0,4):'Date non transmise';}
  function toSeparate(p){return !!p.isolation_required;}
  function status(p){return p.receipt?(p.state==='annule'?'Réceptionné · demande annulée':p.state==='unmatched'?'Réceptionné · sans analyse reçue':'Réceptionné'):p.state==='annule'?'Demande annulée':p.scanned_at?'Pointage annulé':'Non réceptionné';}
  function tracking(p){
    const pending=p.pending_issues?.length,handled=p.last_handling,decision=p.tube_disposition;
    if(pending&&S.user.role!=='viewer'&&state.confirming?.sample_id===p.sample_id){
      // Each pending situation gets its own question; « Confirmer ? » appears once every answer is given.
      const c=state.confirming,issues=p.pending_issues||[],hasError=issues.some(i=>i.kind==='error'),hasCancel=!hasError&&issues.some(i=>i.kind==='cancelled');
      const dupAnswers={same_tube:'Il n’y a qu’un seul tube : je l’ai scanné deux fois par inattention.',two_tubes_regularized:'Deux échantillons portaient par erreur le même code-barres. J’ai vérifié et le problème est régularisé : je conserve l’échantillon.'};
      const cancelAnswers={cancel_confirmed:'Demande réellement annulée (vérifié sur la prescription). Je retire le tube du lot.',cancel_error:'Demande annulée par erreur : elle est toujours sur la prescription. Je garde le tube pour l’analyse et la demande est à rétablir dans le SIL.'};
      const select=(cls,prompt,answers,value)=>`<select class="${cls} ${!value?'pcr-choice-prompt':''}" data-sample="${esc(p.sample_id)}" aria-label="${esc(prompt)}" title="${esc(answers[value]||prompt)}"><option value="">${esc(prompt)}</option>${Object.entries(answers).map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
      const parts=[p.pending_duplicate?select('pcr-duplicate-choice','DOUBLE SCAN : expliquez ?',dupAnswers,c.duplicate_action||''):'',hasCancel?select('pcr-cancel-choice','DEMANDE ANNULÉE : expliquez ?',cancelAnswers,c.cancel_action||''):''].join('');
      const ready=(!p.pending_duplicate||c.duplicate_action)&&(!hasCancel||c.cancel_action);
      const hint=[dupAnswers[c.duplicate_action],cancelAnswers[c.cancel_action]].filter(Boolean).join(' ')||'Je confirme avoir retiré ce tube du lot PCR';
      return `<span class="pcr-inline-confirm">${parts||'<span class="pcr-withdraw-confirm">Retiré du lot PCR</span>'}<label ${ready?'':'hidden'} title="${esc(hint)}"><input type="checkbox" class="pcr-confirm-check" data-sample="${esc(p.sample_id)}" ${ready?'':'disabled'}>Confirmer ?</label></span>`;
    }
    const noAction=p.state==='annule'&&!p.has_physical_scan&&!pending;
    const label=pending?(S.user.role==='viewer'?'Action en attente':'Traiter'):noAction?'Aucune action requise':decision?decision.label+' · '+decision.actor:handled?'Décision non précisée · '+handled.actor:p.scanned_at?'Scanné par '+p.scanned_at.actor:'Suivi';
    const hint=noAction?'Tube non scanné · consulter l’historique':decision?decision.label+' · '+decision.actor+' · '+dateLabel(decision.at):handled?'Ancienne confirmation sans décision sur le lot PCR : '+handled.label+' · '+handled.actor+' · '+dateLabel(handled.at):'';
    return `<button class="pcr-tracking ${pending?'pcr-to-handle':decision?.state==='removed'?'pcr-withdrawn':handled?'pcr-handled':''}" data-action="pcr-tracking" data-sample="${esc(p.sample_id)}" title="${esc(hint||label)}">${esc(label)}</button>`+(p.reactivated_request?'<span class="pcr-reactivated" title="Analyse réactivée depuis le précédent traitement : confirmer le retour du tube en PCR">Analyse réactivée</span>':'');
  }
  async function trackingDialog(sid){
    const data=await api('/pcr/history?sample_id='+encodeURIComponent(sid)),p=data.pair,issues=p.pending_issues||[];
    const actions={tube_scanned:'Tube scanné',received:'Échantillon scanné',scan_repeated:'Nouveau scan',tube_handled:'Action confirmée',receipt_cancelled:'Pointage annulé',orders_imported:'Analyses actualisées',orders_received_mca:'Analyses reçues du SIL/middleware',analysis_done_mca:'Analyse signalée faite par le SIL/middleware',alerts_updated:'Alertes actualisées',tracking_initialized:'Suivi activé',comment_added:'Commentaire',mail_generated:'Mail de relance généré'};
    const history=data.events.map(e=>`<li><time>${esc(dateLabel(e.at))}</time><strong>${esc(e.actor)}</strong><span>${esc(e.action==='tube_handled'?[e.detail.disposition?.label,e.detail.label].filter(Boolean).join(' · '):actions[e.action]||e.action)}${e.detail.comment?' — '+esc(e.detail.comment.text):''}${e.detail.duplicate?' · code-barres déjà scanné':''}${e.detail.note?' — '+esc(e.detail.note):''}${e.detail.reason?' — '+esc(e.detail.reason):''}</span></li>`).join('');
    showModal('Historique du tube '+sid,`<p>${esc(p.patient||'Patient non transmis')} · Dossier ${esc(p.dossier||'non transmis')}</p>${issues.length?`<p>${esc(p.pending_reasons.map(displayText).join(' · '))}</p>`:'<p class="pcr-handled">Aucune action en attente.</p>'}<ol class="pcr-history">${history}</ol>`,true);
  }
  async function acknowledge(input){
    const [sid,code]=input.dataset.key.split('|');input.disabled=true;
    const p=state.data?.pairs.find(p=>p.sample_id===sid&&(p.request_code||'')===code);
    const ids=(p?.comments||[]).filter(c=>c.to_ack&&!c.ack).map(c=>c.id);
    await run(async()=>{try{for(const id of ids)await api('/pcr/comment/ack',{sample_id:sid,comment_id:id});toast(sid+' : commentaire acquitté.');}finally{state.acking=null;await load();}});
  }
  async function confirmInline(input){
    if(!input.checked)return;
    if(busy||state.confirming?.sample_id!==input.dataset.sample){input.checked=false;return;}
    const confirmation={...state.confirming};input.disabled=true;
    await run(async()=>{
      try{
        // Error: always removed. Cancellation: the technician's answer. Duplicate alone: kept.
        const p=state.data?.pairs.find(p=>p.sample_id===confirmation.sample_id),issues=p?.pending_issues||[];
        const hasError=issues.some(i=>i.kind==='error'),hasCancel=issues.some(i=>i.kind==='cancelled');
        const action=hasError?'removed':hasCancel?(confirmation.cancel_action||'removed'):confirmation.duplicate_action?'kept':'removed';
        const {cancel_action,...body}=confirmation;
        const result=await api('/pcr/handle',{...body,action,confirmed:true});
        state.confirming=null;
        notice(result.sample_id+' : '+result.pairs[0].tube_disposition.label+' · '+result.pairs[0].last_handling.actor+'.');
        await load();toast('Action enregistrée. Compteurs actualisés.');
      }catch(e){state.confirming=null;try{await load();}catch{renderList();}throw e;}
    });
  }
  document.addEventListener('change',e=>{
    if(e.target.matches('.pcr-duplicate-choice')&&state.confirming?.sample_id===e.target.dataset.sample){state.confirming.duplicate_action=e.target.value;renderList();}
    if(e.target.matches('.pcr-cancel-choice')&&state.confirming?.sample_id===e.target.dataset.sample){state.confirming.cancel_action=e.target.value;renderList();}
    if(e.target.matches('.pcr-confirm-check'))confirmInline(e.target);
    if(e.target.matches('.pcr-ack-confirm')&&e.target.checked)acknowledge(e.target);
    if(e.target.matches('.pcr-mail-check')){const k=e.target.dataset.key;if(e.target.checked)state.mailSel.add(k);else state.mailSel.delete(k);const mc=$('#pcr-mail-count');if(mc)mc.textContent=state.mailSel.size;}
  });
  function doneDot(p){if(!p.request_code)return '';const done=p.analysis_done,label=done?'Analyse faite · signalée par le SIL/middleware le '+dateLabel(done.at):p.done_code?'Analyse non signalée comme faite':'Suivi « analyse faite » non paramétré pour cette analyse';return `<span class="pcr-done ${done?'pcr-done-yes':p.done_code?'':'pcr-done-off'}" role="img" aria-label="${esc(label)}" title="${esc(label)}"></span>`;}
  function patientColor(key){let n=0;for(const c of key)n=(n*31+c.charCodeAt(0))>>>0;return ['#168d98','#8576ae','#b0804e','#43866e','#527ea7'][n%5];}
  function commentCell(p){
    const list=p.comments||[],pending=list.filter(c=>c.to_ack&&!c.ack),last=pending[0]||list[list.length-1];
    const hint=list.length?list.map(c=>`${dateLabel(c.at)} · ${c.actor} : ${c.text}`).join('\n'):'Ajouter un commentaire';
    const toAck=pending.length>0;
    return `<button class="pcr-comment-btn ${list.length?'pcr-has-comment':''} ${toAck?'pcr-comment-to-ack':''}" data-action="pcr-comments" data-sample="${esc(p.sample_id)}" data-code="${esc(p.request_code||'')}" title="${esc(hint)}">${list.length?`<b>${toAck?'⚑ ':''}${list.length}</b> ${esc(last.actor)} : ${esc(last.text)}`:'+ Commenter'}</button>`;
  }
  // Only the author, and only for the comment just written (latest of the line).
  function ownerTools(c,sid){
    if(S.user.role==='viewer'||c.actor!==S.user.username||!c.latest)return '';
    if(state.editingComment===c.id)return '';
    return `<span class="pcr-comment-tools"><button data-action="pcr-comment-edit" data-comment="${esc(c.id)}">Modifier</button><button data-action="pcr-comment-delete" data-sample="${esc(sid)}" data-comment="${esc(c.id)}">Supprimer</button>${c.to_ack?'':`<button data-action="pcr-comment-toack" data-sample="${esc(sid)}" data-comment="${esc(c.id)}">Rendre à acquitter</button>`}</span>`;
  }
  function commentText(c,sid){
    if(state.editingComment===c.id)return `<form id="pcr-comment-edit-form" class="pcr-comment-edit-form" data-sample="${esc(sid)}" data-comment="${esc(c.id)}"><textarea name="text" maxlength="1000" required>${esc(c.text)}</textarea><div class="actions"><button class="primary">Enregistrer</button><button type="button" data-action="pcr-comment-cancel">Annuler</button></div></form>`;
    return esc(c.text)+(c.edited?` <em class="muted" title="${esc('Modifié le '+dateLabel(c.edited.at))}">(modifié)</em>`:'');
  }
  function commentsDialog(sid,code){
    state.commentCtx={sid,code};
    const p=state.data?.pairs.find(p=>p.sample_id===sid&&(p.request_code||'')===code);const list=(p?.comments||[]).map((c,i,a)=>({...c,latest:i===a.length-1}));
    showModal('Commentaires · '+sid+(p?.label?' · '+displayText(p.label):''),`<ol class="pcr-comments">${list.map(c=>`<li><time>${esc(dateLabel(c.at))}</time><strong>${esc(c.actor)}</strong><span>${commentText(c,sid)}${c.request_code?'':' <em class="muted">(tube)</em>'}${ackState(c,sid)}${ownerTools(c,sid)}</span></li>`).join('')||'<li class="muted">Aucun commentaire pour l’instant.</li>'}</ol>${S.user.role==='viewer'?'':`<form id="pcr-comment-form" data-sample="${esc(sid)}" data-code="${esc(code)}"><label>Nouveau commentaire<textarea name="text" maxlength="1000" required placeholder="Visible par tous, avec votre nom et l’heure"></textarea></label><label class="checks pcr-ack-check"><input type="checkbox" name="to_ack">À transmettre : ce commentaire devra être lu et acquitté</label><p class="muted">Seul le dernier commentaire peut être modifié ou supprimé, par son auteur ; l’historique du tube en garde la trace.</p><button class="primary">Ajouter le commentaire</button></form>`}`,true);
    $('#pcr-comment-form textarea')?.focus();
  }
  function ackState(c,sid){
    if(!c.to_ack)return '';
    if(c.ack)return `<span class="pcr-ack-done">✓ Acquitté par ${esc(c.ack.actor)} · ${esc(dateLabel(c.ack.at))}</span>`;
    return `<span class="pcr-ack-wait">⚑ À acquitter (bouton « Commentaires à acquitter »)</span>`;
  }
  function pendingAcks(){
    const seen=new Map();
    for(const p of state.data?.pairs||[])for(const c of p.comments||[])if(c.to_ack&&!c.ack&&!seen.has(c.id))seen.set(c.id,{c,p});
    return [...seen.values()].sort((a,b)=>a.c.at.localeCompare(b.c.at));
  }
  function ackCounter(){const n=pendingAcks().length;return `<button id="pcr-ack-counter" class="pcr-ack-counter ${n?'pcr-ack-pending':''} ${state.filter==='acks'?'active':''}" data-action="pcr-acks" title="Commentaires transmis à acquitter">Commentaires à acquitter <b>${n}</b></button>`;}
  // Acknowledge like « Traiter »: button, then inline « Confirmer ? ».
  function ackAction(p){
    const pending=(p.comments||[]).filter(c=>c.to_ack&&!c.ack),key=p.sample_id+'|'+(p.request_code||'');
    if(!pending.length)return '';
    if(S.user.role==='viewer')return '<span class="pcr-ack-wait">⚑ À acquitter</span>';
    if(state.acking===key)return `<span class="pcr-inline-confirm"><span class="pcr-ack-confirm-label">Commentaire lu</span><label title="Je confirme avoir lu ce commentaire"><input type="checkbox" class="pcr-ack-confirm" data-key="${esc(key)}">Confirmer ?</label></span>`;
    return `<button class="pcr-tracking pcr-ack-todo" data-action="pcr-ack" data-key="${esc(key)}" title="${esc(pending.map(c=>c.actor+' : '+c.text).join('\n'))}">Acquitter</button>`;
  }
  function mailBar(){
    if(state.filter!=='expected'||S.user.role==='viewer')return '';
    if(!state.mailing)return '<div class="pcr-mail-bar"><button class="pcr-mail-start" data-action="pcr-mail-mode">ENVOYER MAILS AUX LABORATOIRES</button></div>';
    return `<div class="pcr-mail-bar pcr-mail-active"><span><strong id="pcr-mail-count">${state.mailSel.size}</strong> échantillon(s) sélectionné(s) · cochez les lignes à relancer (laboratoires avec une adresse)</span>${alertOn('receipt')?'<button data-action="pcr-mail-late">Sélectionner les retards de réception</button>':''}<button data-action="pcr-mail-none">Tout désélectionner</button><button class="primary" data-action="pcr-mail-prepare">Préparer les mails</button><button data-action="pcr-mail-mode">Fermer</button></div>`;
  }
  function frDate(iso){return /^\d{4}-\d{2}-\d{2}/.test(iso||'')?shortDate(iso.slice(0,10)):'non transmise';}
  function buildMails(){
    const chosen=(state.data?.pairs||[]).filter(p=>state.mailSel.has(p.sample_id+'|'+p.request_code)&&p.status==='expected');
    const byAddress=new Map();
    for(const p of chosen){const key=p.lab_email||'sans-adresse:'+p.lab_family+':'+p.lab_code;if(!byAddress.has(key))byAddress.set(key,{to:p.lab_email,labs:new Set(),pairs:[]});const m=byAddress.get(key);m.labs.add(p.lab_family+' '+(p.lab_detail||p.lab_code));m.pairs.push(p);}
    const sender=S.user.display_name||S.user.username;
    const head=['Date du dossier','Dossier','Nom','Prénom','Date de naissance','N° échantillon','Analyse'];
    return [...byAddress.values()].map(m=>{
      // One line per sample and analysis; the date is the dossier date, without the time.
      const rows=m.pairs.map(p=>{const day=(p.requested_at||p.date_demande||'').slice(0,10);return {day,cells:[/^\d{4}-\d{2}-\d{2}$/.test(day)?shortDate(day):'—',p.dossier||'—',p.patient_last||personName(p),p.patient_first||'—',p.birth_date?shortDate(p.birth_date):'—',p.sample_id,displayText(p.label)]};})
        .sort((a,b)=>a.day.localeCompare(b.day)||a.cells[1].localeCompare(b.cells[1])||a.cells[5].localeCompare(b.cells[5])).map(r=>r.cells);
      const widths=head.map((h,i)=>Math.max(h.length,...rows.map(r=>r[i].length)));
      const line=r=>r.map((v,i)=>v.padEnd(widths[i])).join(' | ').trimEnd();
      const textTable=[line(head),widths.map(w=>'-'.repeat(w)).join('-+-'),...rows.map(line)].join('\n');
      const htmlTable=`<table border="1" cellpadding="4" cellspacing="0" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:12px"><tr>${head.map(h=>`<th style="background:#e9f0f2">${esc(h)}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</table>`;
      const labs=[...m.labs].join(', ');
      const subject=`${LAB.short} — Échantillons PCR non reçus — ${labs}`;
      const intro='Bonjour,\n\nNous n’avons pas encore reçu les échantillons suivants:\n\n',outro=`\n\nPouvez-vous vérifier s’ils ont bien été envoyés et nous tenir informés ?\n\nMerci et bonne journée,\n${sender}\n${LAB.service}`;
      const html=`<div style="font-family:Arial,sans-serif;font-size:13px">${esc(intro).replace(/\n/g,'<br>')}${htmlTable}${esc(outro).replace(/\n/g,'<br>')}</div>`;
      return {to:m.to,labs,subject,body:intro+textTable+outro,html,htmlTable,count:new Set(m.pairs.map(p=>p.sample_id)).size,
              keys:m.pairs.map(p=>({sample_id:p.sample_id,request_code:p.request_code})),lastMail:lastMail(m.pairs)};
    });
  }
  function mailto(m){return 'mailto:'+m.to+'?subject='+encodeURIComponent(m.subject)+'&body='+encodeURIComponent(m.body.replace(/\n/g,'\r\n'));}
  // Latest « mail generated » trace among these lines, if any.
  function lastMail(pairs){return pairs.flatMap(p=>p.mails||[]).sort((a,b)=>b.at.localeCompare(a.at))[0]||null;}
  function mailCard(m,i){
    const done=m.generated||m.lastMail;
    return `<section class="pcr-mail-card ${done?'pcr-mail-done':''}" id="pcr-mail-card-${i}"><h3>${esc(m.labs)} <small>${esc(countLabel(m.count,'échantillon'))}</small>${done?`<span class="pcr-mail-stamp">✉ Mail généré le ${esc(dateLabel(done.at))} · ${esc(done.actor)}</span>`:''}</h3>${m.to?`<p>À : <strong>${esc(m.to)}</strong></p>`:'<p class="form-error">Adresse mail non paramétrée pour ce laboratoire : à compléter dans Paramètres PCRLia → Laboratoires et dossiers.</p>'}<p>Objet : ${esc(m.subject)}</p><div class="pcr-mail-body">${m.html}</div><div class="actions">${m.to?`<button class="${done?'':'primary'}" data-action="pcr-mail-open" data-index="${i}">${done?'Regénérer le brouillon':'Générer le brouillon dans Thunderbird'}</button>`:''}<button data-action="pcr-mail-copy" data-index="${i}">Copier le tableau</button></div></section>`;
  }
  function mailsDialog(){
    state.mails=buildMails();
    if(!state.mails.length)throw new Error('Cochez au moins un échantillon non réceptionné à relancer.');
    const sendable=state.mails.filter(m=>m.to).length;
    showModal('Relance des laboratoires · '+countLabel(state.mails.length,'mail'),`<p>Un mail par adresse de laboratoire. Chaque bouton ouvre un brouillon dans votre messagerie (Thunderbird si c’est la messagerie par défaut du poste) : vérifiez-le, puis envoyez-le vous-même. Rien n’est envoyé par PCRLia. Chaque génération affiche l’icône ✉ bleue sur les échantillons concernés.</p>${sendable>1?`<div class="actions"><button class="primary" data-action="pcr-mail-all">Générer les ${sendable} brouillons</button><span class="muted">Si la messagerie demande l’autorisation d’ouvrir les liens, choisissez « Toujours autoriser ».</span></div>`:''}${state.mails.map(mailCard).join('')}<p class="muted">Le brouillon contient le tableau en texte. Pour un vrai tableau quadrillé : « Copier le tableau », puis dans le brouillon sélectionner le tableau texte et coller à la place (Ctrl+V).</p>`);
  }
  function launchMail(m){const a=document.createElement('a');a.href=mailto(m);a.style.display='none';document.body.append(a);a.click();a.remove();}
  async function openMails(indexes){
    const pause=ms=>new Promise(r=>setTimeout(r,ms));let n=0;
    for(const i of indexes){const m=state.mails[i];if(!m?.to)continue;
      if(n++)await pause(1200);
      launchMail(m);
      await api('/pcr/mail-log',{to:m.to,pairs:m.keys});
      m.generated={at:new Date().toISOString(),actor:S.user.display_name||S.user.username};
      const card=$('#pcr-mail-card-'+i);if(card)card.outerHTML=mailCard(m,i);
    }
    const all=document.querySelector('[data-action=pcr-mail-all]');if(all&&state.mails.every(m=>!m.to||m.generated||m.lastMail))all.textContent='Regénérer les '+state.mails.filter(m=>m.to).length+' brouillons';
    await load();toast(countLabel(n,'brouillon généré','brouillons générés')+' · icône ✉ ajoutée sur les échantillons.');
  }
  function table(pairs,preview=false){
    const view=preview?'':state.filter,scanning=view==='scan',errorsView=view==='errors',timed=view==='expected',doneView=view==='done',waitingView=view==='waiting',mailing=timed&&state.mailing,cols=(timed?9:8);
    const series=p=>(p.analysis_done?.at||'').slice(0,13);
    const sorted=scanning?[...pairs].sort((a,b)=>(b.scanned_at?.at||'').localeCompare(a.scanned_at?.at||'')):doneView?[...pairs].sort((a,b)=>series(b).localeCompare(series(a))||[a.site,patientKey(a),a.dossier,a.sample_id,a.request_code].join('\u0001').localeCompare([b.site,patientKey(b),b.dossier,b.sample_id,b.request_code].join('\u0001'),'fr')):[...pairs].sort((a,b)=>{const av=state.order==='date'?[a.date_demande||'9999',a.site]:[a.site,a.date_demande||'9999'];const bv=state.order==='date'?[b.date_demande||'9999',b.site]:[b.site,b.date_demande||'9999'];if(timed){av.push(a.heure_demande||'99:99');bv.push(b.heure_demande||'99:99');}if(waitingView){av.push(a.receipt?.at||'');bv.push(b.receipt?.at||'');}return [...av,patientKey(a),a.dossier,a.sample_id,a.request_code].join('\u0001').localeCompare([...bv,patientKey(b),b.dossier,b.sample_id,b.request_code].join('\u0001'),'fr',{numeric:false});});
    const counts=new Map();for(const p of state.data?.pairs||pairs){const key=patientKey(p);if(!counts.has(key))counts.set(key,{samples:new Set(),dossiers:new Set()});counts.get(key).samples.add(p.sample_id);if(p.dossier)counts.get(key).dossiers.add(p.dossier);}
    const seriesSize=new Map();if(doneView)for(const p of pairs)seriesSize.set(series(p),(seriesSize.get(series(p))||new Set()).add(p.sample_id));
    let previous='',lastPatient='',html='';
    for(const p of sorted){
      if(doneView){const s=series(p);if(s!==previous){const hour=Number(s.slice(11,13)),n=seriesSize.get(s).size;html+=`<tr class="pcr-group pcr-series"><th colspan="${cols}"><strong>${esc(shortDate(s.slice(0,10)))} · série ${String(hour).padStart(2,'0')} h – ${String((hour+1)%24).padStart(2,'0')} h</strong><span>${esc(countLabel(n,'échantillon'))} · résultat signalé par le SIL/middleware dans cette heure</span></th></tr>`;previous=s;lastPatient='';}}
      else{const group=JSON.stringify([p.date_demande,p.site]);if(!scanning&&group!==previous){const first=state.order==='date'?shortDate(p.date_demande):(p.site||'Laboratoire non transmis'),second=state.order==='date'?(p.site||'Laboratoire non transmis'):shortDate(p.date_demande);html+=`<tr class="pcr-group"><th colspan="${cols}"><strong>${esc(displayText(first))}</strong><span>${esc(displayText(second))}</span></th></tr>`;previous=group;lastPatient='';}}
      const key=patientKey(p),same=lastPatient===key,info=counts.get(key),related=info?.samples.size>1;
      const hint=p.patient_id?`Patient ${p.patient_id} · ${info?.samples.size||1} échantillon(s) · ${info?.dossiers.size||0} dossier(s)`:p.dossier?'Association par dossier uniquement — identifiant patient non transmis':'Identité patient non transmise';
      const patient=p.patient||p.patient_id||'Non transmis',mailable=mailing&&['Réseau A','Réseau C','Réseau B'].includes(p.lab_family),mailKey=p.sample_id+'|'+p.request_code;
      const late=timed?receiptLate(p):waitingView?resultLate(p):0;
      const duplicateTimes=p.pending_duplicate&&p.scans?.length>1?`<span class="pcr-dup-times" title="${esc('DOUBLE SCAN — aller vérifier l’échantillon scanné précédemment\n'+scanTimes(p.scans).join('\n'))}">DOUBLE SCAN ${esc(p.scans.map(s=>stamp(s.at)).join(' → '))}</span>`:'';
      html+=`<tr class="pcr-row ${same?'pcr-same-patient':''} ${p.pending_error?'pcr-error-row':p.pending_cancelled?'pcr-cancelled-row':''} ${late?(timed?'pcr-late-row pcr-late-receipt-row':'pcr-late-row pcr-late-result-row'):''}" data-sample="${esc(p.sample_id)}" data-code="${esc(p.request_code)}" style="--patient-color:${patientColor(key)}"><td class="pcr-patient" title="${esc((p.patient||p.patient_id||'Non transmis')+' · '+hint)}">${mailable?`<input type="checkbox" class="pcr-mail-check" data-key="${esc(mailKey)}" aria-label="Relancer ${esc(p.sample_id)}" ${state.mailSel.has(mailKey)?'checked':''}>`:''}${preview||scanning?esc(patient):`<button class="pcr-patient-link" data-action="pcr-patient" data-patient="${esc(key)}">${esc(patient)}${related?`<span class="pcr-related">${info.samples.size}</span>`:''}</button>`}</td><td class="pcr-barcode" title="${esc([p.site_resolved||p.site,p.lab_detail,p.lab_code].filter(Boolean).join(' · '))}">${esc(p.sample_id)}</td>${timed?`<td class="pcr-time" title="${p.heure_demande?'Heure de transmission du dossier par le SIL/middleware':'Heure non transmise'}">${esc(p.heure_demande||'—')}</td>`:''}<td title="${esc(displayText(p.label)+' · Code automate : '+p.request_code)}">${preview?'':doneDot(p)}${esc(displayText(p.label))}</td><td title="${esc(displayText(errorsView?errorReasons(p):groupName(p.group)))}">${esc(displayText(errorsView?errorReasons(p):groupName(p.group)))}</td><td>${esc(p.dossier||'—')}</td><td class="${p.receipt?'pcr-received':'pcr-waiting'}" title="${esc([...(p.error_reasons||[]),p.scanned_at?dateLabel(p.scanned_at.at)+' · '+p.scanned_at.actor:''].filter(Boolean).join(' · '))}">${lateChip(late,timed?'receipt':'result')}${(()=>{const m=timed?lastMail([p]):null;return m?`<span class="pcr-mailed" title="${esc('Mail de relance généré le '+dateLabel(m.at)+' par '+m.actor)}">✉ ${esc(stamp(m.at))}</span> `:'';})()}${toSeparate(p)&&!duplicateTimes?'<span class="pcr-separate-label">ATTENTION</span> ':''}${duplicateTimes||((waitingView||doneView)&&p.receipt?'Reçu '+esc(stamp(p.receipt.at)):esc(status(p)))}${doneView?` <span class="pcr-result-time">· résultat ${esc(clock(p.analysis_done.at))}</span>`:''}${!duplicateTimes&&!preview&&(scanning||state.filter==='scanned')&&p.scanned_at?` <span class="pcr-scan-date">· ${esc(p.scanned_at.actor)} · ${dateLabel(p.scanned_at.at)}</span>`:''}</td><td>${preview?'—':state.filter==='acks'?ackAction(p):tracking(p)}</td><td>${preview?'—':commentCell(p)}</td></tr>`;lastPatient=key;
    }
    const empty=scanning?'Les échantillons apparaîtront ici après leur scan.':(doneView||waitingView)?'Aucun échantillon. Seules les analyses ayant un code « analyse faite » paramétré sont suivies ici.':'Aucun échantillon dans cette sélection.';
    return `<div class="pcr-table-wrap"><table class="pcr-table pcr-cols-${cols}${timed?' pcr-timed':''}"><thead><tr><th>Patient</th><th>Échantillon</th>${timed?'<th>Heure</th>':''}<th>Analyse</th><th>${errorsView?'Motif':'Type de PCR'}</th><th>Dossier</th><th>Réception</th><th>Suivi / action</th><th>Commentaires</th></tr></thead><tbody>${html||`<tr><td colspan="${cols}" class="pcr-empty">${empty}</td></tr>`}</tbody></table></div>`;
  }
  function renderList(){
    const pairs=filtered(),actions=['cancelled','errors'].includes(state.filter);
    const counts=selectionCounts(actions?pairs.filter(p=>needsAction(p,state.filter)):pairs);
    const el=$('#pcr-list');if(el)el.innerHTML=table(pairs);
    const count=$('#pcr-filter-count');if(count){
      count.textContent=countLabel(counts.requests,'dossier')+' · '+countLabel(counts.samples,'échantillon')+(actions?' à traiter':'')+(counts.withoutDossier?' · '+countLabel(counts.withoutDossier,'échantillon sans dossier','échantillons sans dossier'):'');
      count.title=actions?'Cas nécessitant encore une action dans cette sélection. Les lignes déjà traitées restent consultables.':'Chaque dossier et chaque échantillon sont comptés une seule fois.';
    }
    for(const badge of document.querySelectorAll('[data-pcr-count]')){const c=navCount(badge.dataset.pcrCount);badge.textContent=c.value;badge.title=c.title;}
    for(const sub of document.querySelectorAll('[data-pcr-dossiers]')){const id=sub.dataset.pcrDossiers,c=navCount(id);sub.textContent=['waiting','done'].includes(id)?(id==='waiting'?(c.late?countLabel(c.late,'en retard','en retard'):'aucun retard'):countLabel(c.dossiers,'dossier','dossiers')):countLabel(c.dossiers,'dossier concerné','dossiers concernés')+(c.late?' · '+countLabel(c.late,'en retard','en retard'):'');sub.classList.toggle('pcr-sub-late',!!c.late);sub.title=c.title;}
    const mc=$('#pcr-mail-count');if(mc)mc.textContent=state.mailSel.size;const ac=$('#pcr-ack-counter');if(ac)ac.outerHTML=ackCounter();
    const clear=$('#pcr-clear-patient');if(clear)clear.hidden=!state.patient;
  }
  function nav(items,secondary=false){return `<div class="pcr-nav ${secondary?'pcr-nav-secondary':'pcr-nav-primary'}">${items.map(id=>`<button data-action="pcr-filter" data-filter="${id}" class="${state.filter===id?'active':''}" ${state.filter===id?'aria-current="page"':''}><span class="pcr-nav-line"><span>${titles[id]}</span>${id==='scan'?'':`<b data-pcr-count="${id}"></b>`}</span>${['expected','cancelled','waiting','done'].includes(id)?`<small data-pcr-dossiers="${id}"></small>`:id==='scan'?'<small>Commencer le pointage</small>':''}</button>`).join('')}</div>`;}

  function render(){
    const activeElement=document.activeElement,draft=$('#pcr-barcode')?.value||'',focus=activeElement?.id,cursor=focus==='pcr-search'?activeElement.selectionStart:null;
    // Result follow-up is hidden entirely while its alert is off.
    if(['waiting','done'].includes(state.filter)&&!alertOn('result'))state.filter='scan';
    const data=state.data||{pairs:[],codes:[],groups:[],source:{}},writable=S.user.role!=='viewer',scanning=state.filter==='scan';
    const sites=[...new Set(data.pairs.map(p=>p.site).filter(Boolean))].sort();
    if(state.site&&!sites.includes(state.site))state.site='';
    $('#app').innerHTML=`<div class="layout pcr-layout"><aside class="sidebar">${brand()}${Workspaces.switcher()}<div class="specialty">Réception des prélèvements<br><em>Pointage PCR</em></div>${nav(['scan','expected'])}${alertOn('result')?`<div class="pcr-registers pcr-followup"><h3>Suivi résultats</h3>${nav(['waiting','done'],true)}</div>`:''}<div class="pcr-registers"><h3>Registres</h3>${nav(['scanned','requests','cancelled','errors'],true)}</div><div class="sidebar-foot">${S.user.role==='admin'?'<button data-action="pcr-settings">Paramètres PCRLia</button><button data-action="accounts">Utilisateurs et affectations</button>':''}<a class="guide-link" href="/guide" target="_blank" rel="noopener" title="Ouvre le guide dans un nouvel onglet">📘 Guide du technicien</a><button data-action="logout">Déconnexion</button>${versionTag()}</div></aside><div class="workspace"><header class="topbar"><span class="lab-heading"><strong>${esc(LAB.short)}</strong><span class="topbar-divider"></span><span>PCRLia · Réception</span></span><span class="local">${esc(S.user.display_name||S.user.username)}</span></header><main class="content"><div class="pcr-heading"><h1>${titles[state.filter]}</h1><div class="actions">${ackCounter()}<button data-action="pcr-refresh">Actualiser</button>${S.user.role==='admin'?'<button data-action="pcr-import">Importer les analyses</button>':''}<button data-action="pcr-print">Imprimer</button></div></div><div class="pcr-source ${data.source.pending||data.source.error?'pcr-source-warning':''}" title="${esc(data.source.last_import?'Dernier import : '+dateLabel(data.source.last_import.at)+' · '+data.source.last_import.source:'Aucun import d’analyses')}"><span>${esc(sourceLabel(data.source))}</span>${data.source.pending||data.source.error?'<button data-action="pcr-reception-issues">Voir le problème</button>':''}<span id="pcr-refresh-status">${data.at?'Actualisé à '+new Date(data.at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):''}</span></div>${scanning?`<section class="panel pcr-scan">${writable?`<form id="pcr-scan-form"><label>Scanner l’échantillon<input id="pcr-barcode" name="sample_id" autocomplete="off" spellcheck="false" maxlength="80" placeholder="Code-barres complet, puis Entrée" required></label><button class="primary">Réceptionner</button></form><div id="pcr-notice" class="pcr-notice ${noticeClass()}" role="alert" aria-live="assertive">${noticeHtml()}</div><div id="pcr-failed">${failedView()}</div>`:'<p>Accès en consultation.</p>'}</section>`:''}<section class="panel pcr-results"><div class="pcr-results-head"><h2>${scanning?'Échantillons scannés':titles[state.filter]}</h2><span id="pcr-filter-count" aria-live="polite" aria-atomic="true"></span></div>${scanning?'':`<div class="pcr-filters"><label>Rechercher<input id="pcr-search" value="${esc(state.search)}" placeholder="Patient, échantillon, dossier…"></label><label>Type de PCR<select id="pcr-group"><option value="">Tous les types</option>${data.groups.map(g=>`<option value="${g.id}" ${state.group===g.id?'selected':''}>${esc(g.label)}</option>`).join('')}</select></label><label>Laboratoire<select id="pcr-site"><option value="">Tous les laboratoires</option>${sites.map(s=>`<option ${s===state.site?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Classer par<select id="pcr-order"><option value="date" ${state.order==='date'?'selected':''}>Date puis laboratoire</option><option value="site" ${state.order==='site'?'selected':''}>Laboratoire puis date</option></select></label><label>Du<input id="pcr-from" type="date" value="${state.from}"></label><label>Au<input id="pcr-to" type="date" value="${state.to}"></label></div><div class="pcr-period">${state.from===defaultFrom()&&!state.to?'Affichage : 2 dernières semaines · <button data-action="pcr-all-dates">Afficher tous les dossiers</button>':state.from||state.to?'Période choisie · <button data-action="pcr-all-dates">Afficher tous les dossiers</button> <button data-action="pcr-two-weeks">2 dernières semaines</button>':'Affichage : tous les dossiers · <button data-action="pcr-two-weeks">2 dernières semaines</button>'}</div><button id="pcr-clear-patient" class="pcr-clear-patient" data-action="pcr-clear-patient" ${state.patient?'':'hidden'}>Retirer le filtre patient / dossier ×</button>${mailBar()}`}<div id="pcr-list"></div></section></main></div></div>`;
    renderList();const input=$('#pcr-barcode');if(input)input.value=draft;const focused=focus&&document.getElementById(focus);if(focused){focused.focus();if(cursor!==null)focused.setSelectionRange(cursor,cursor);}else if(scanning&&!modal.open){input?.focus();}
  }
  function failedView(){return state.failed.map((f,i)=>`<p class="pcr-warning">${esc(f.sample_id)} : pointage non confirmé. <button data-action="pcr-retry" data-index="${i}">Réessayer</button> <button data-action="pcr-dismiss-failure" data-index="${i}">Retirer l’alerte</button></p>`).join('');}
  async function load(){const data=await api('/pcr/samples');if(S.workspace!=='pcrlia'||!S.user)return;state.data=data;
    if(state.confirming&&!data.pairs.some(p=>p.sample_id===state.confirming.sample_id&&p.revision===state.confirming.revision&&p.pending_issues?.length)){state.confirming=null;}
    if(state.notice?.separate&&state.notice.sample){const p=data.pairs.find(p=>p.sample_id===state.notice.sample);if(p&&!p.pending_issues?.length)notice(p.sample_id+' : '+(p.last_handling?p.last_handling.label+' · '+p.last_handling.actor+'.':'aucune action en attente après actualisation des analyses ou du paramétrage.'));}
    render();schedule();}
  function schedule(){stop();state.timer=setTimeout(async()=>{if(S.workspace!=='pcrlia'||!S.user)return;try{if(!modal.open&&!state.draining&&!busy)await load();else schedule();}catch(e){const el=$('#pcr-refresh-status');if(el)el.textContent='Actualisation impossible — données anciennes';schedule();}},15000);}
  function noticeClass(){return state.notice?.separate?'pcr-separate-alert '+(state.notice.kind==='cancelled'?'pcr-cancelled-alert':'pcr-error-alert'):state.notice?.error?'pcr-warning':'';}
  function noticeHtml(){
    const n=state.notice,scans=n?.duplicate?n.scans||[]:[];
    // Duplicate scan: short, the sample, the scan times and the action only.
    if(n?.separate&&n.duplicate)return `<strong>${esc(n.sample)} · DOUBLE SCAN — vérifier l’échantillon précédent</strong>${scans.length>1?`<span class="pcr-dup-list"><span class="pcr-dup-warn">⚠ Bien regarder les heures de scan :</span>${scans.map((s,i)=>`<b class="${i===scans.length-1?'pcr-dup-current':''}">${esc(ordinal(i+1))} scan ${esc(stamp(s.at))} · ${esc(s.actor)}${i===scans.length-1?' (actuel)':''}</b>`).join('')}</span>`:''}`+(n.sample?`<button class="pcr-notice-action" data-action="pcr-tracking" data-sample="${esc(n.sample)}">Valider mon action</button>`:'');
    return (n?.separate?(n.kind==='cancelled'?`<strong>ATTENTION — DEMANDE ANNULÉE</strong><span>Mettre le tube de côté et vérifier sur la prescription si la demande est vraiment annulée, puis « Traiter ».</span>`:`<strong>RETIRER CE TUBE DU LOT</strong><span>Mettre physiquement cet échantillon à l’écart des tubes à passer.</span>`):'')+`<span>${esc(n?.text||'Prêt à scanner. Les analyses du tube sont retrouvées automatiquement.')}</span>`+(state.notice?.separate&&state.notice.sample?`<button class="pcr-notice-action" data-action="pcr-tracking" data-sample="${esc(state.notice.sample)}">Valider mon action</button>`:'');}
  function notice(text,error=false,kind='error',separate=false,sample='',duplicate=false,scans=[]){state.notice={text,error,kind,separate,sample,duplicate,scans};const el=$('#pcr-notice');if(el){el.className='pcr-notice '+noticeClass();el.innerHTML=noticeHtml();}}

  function enqueue(data){const sid=(data.sample_id||'').trim();if(!sid)return;state.queue.push({sample_id:sid,request_id:crypto.randomUUID()});$('#pcr-barcode').value='';$('#pcr-barcode').focus();drain();}
  async function drain(){if(state.draining)return;state.draining=true;try{while(state.queue.length){const job=state.queue.shift();try{
    const result=await api('/pcr/scan',job);
    const detail=[result.matched_count?`${result.matched_count} analyse(s) associée(s).`:'',result.cancelled_count?`${result.cancelled_count} analyse(s) annulée(s).`:'',!result.matched_count&&!result.cancelled_count?'Analyse non transmise ; scan conservé.':''].filter(Boolean).join(' ');
    const p=result.pairs[0],reasons=p.pending_reasons||[];
    notice(`${result.sample_id} : ${p.reactivated_request?'Analyse réactivée — confirmer le retour du tube en PCR. ':''}${p.pending_error?'ÉCHANTILLONS EN ERREUR — ':''}${reasons.length?reasons.map(displayText).join(' · ')+'. Scan conservé.':result.replayed?'scan déjà traité.':'réception enregistrée.'} ${detail}`,!!reasons.length,p.pending_error?'error':'cancelled',!!reasons.length,result.sample_id,p.pending_duplicate,result.scans||p.scans||[]);
  }catch(e){state.failed.push(job);notice(`${job.sample_id} : ${e.message}`,true);}}try{await load();}catch(e){notice('Actualisation indisponible. Les données affichées peuvent être anciennes.',true);const el=$('#pcr-failed');if(el)el.innerHTML=failedView();}}finally{state.draining=false;$('#pcr-barcode')?.focus();}}
  function sourceLabel(source){return source.message+(source.pending?` · ${countLabel(source.pending,'message à examiner','messages à examiner')}`:'');}
  async function mca(){
    const s=await api('/pcr/mca'),c=s.config;
    showModal('Paramètres PCRLia · Connexion SIL/middleware (format Phadia)',`${settingsTabs()}<p>Connexion dédiée : <strong>PCRLia</strong> · format <strong>Phadia / Full download</strong>.</p><div class="banner ${s.error||s.pending?'warning':'info'}" role="status">${esc(sourceLabel(s))}${s.last_received?'<br>Dernier message intégré : '+esc(dateLabel(s.last_received)):''}</div><form id="pcr-mca-form"><label class="checks"><input type="checkbox" name="enabled" ${c.enabled?'checked':''}>Activer la réception des analyses PCR</label><div class="grid2">${field('listen_address','Adresse IPv4 du PC hébergeur',c.listen_address,'text','required')}${field('port','Port dédié à PCRLia',c.port,'number','required min="1024" max="65535"')}${field('mca_address','Adresse IPv4 du SIL/middleware',c.mca_address,'text','required')}<label>Encodage<select name="encoding">${[['cp1252','Windows (accents)'],['ascii','ASCII'],['utf-8','UTF-8']].map(([value,label])=>`<option value="${value}" ${c.encoding===value?'selected':''}>${label}</option>`).join('')}</select></label>${field('raw_retention_days','Conserver les messages bruts intégrés (jours)',c.raw_retention_days,'number','required min="1" max="3650"')}</div><p>Les messages bruts intégrés sont effacés après ce délai. Les analyses, scans, historiques et messages à examiner sont conservés. ${s.purged_messages||0} message(s) brut(s) nettoyé(s).</p>${s.retention_error?`<p class="form-error">${esc(s.retention_error)}</p>`:''}<p>Les analyses arrivent sans scanner. Le scan confirme ensuite la présence physique du tube. Les codes ignorés se règlent dans « Codes ignorés ».</p><button class="primary">Enregistrer la réception PCRLia</button></form>${s.issues?.length?`<h3>Messages à examiner</h3><ul>${s.issues.map(i=>`<li>${esc(dateLabel(i.at))} · ${esc(displayText(i.error))}</li>`).join('')}</ul><p>Après correction des codes ou de l’encodage, réexaminer les messages conservés. Une transmission interrompue nécessite un nouvel envoi dans le SIL/middleware.</p><button data-action="pcr-mca-retry">Réexaminer les messages conservés</button>`:''}<button data-action="pcr-mca" class="pcr-config-title">Actualiser l’état et les messages</button>`);
  }
  function reincludeButton(){return '<div class="pcr-reinclude"><button data-action="pcr-mca-reinclude">Réinclure les dossiers concernés</button><p class="muted">Après ajout d’un code, reprendre les messages encore conservés, sans doublon.</p></div>';}
  function ignoredRow(code=''){return `<tr class="pcr-ignore-row"><td>${code?`<strong class="mono">${esc(code)}</strong><input type="hidden" name="code" value="${esc(code)}">`:'<input name="code" aria-label="Code SIL/middleware à ignorer" maxlength="80" placeholder="Ex. SC2FabR" required>'}</td><td>${code?'Ignoré':'À enregistrer'}</td><td><button type="button" data-action="pcr-remove-ignored">Retirer</button></td></tr>`;}
  async function ignoredCodes(){
    const c=await api('/pcr/config'),codes=c.ignored_mca_codes||[];state.ignoreConfig=c;
    showModal('Paramètres PCRLia · Codes SIL/middleware à ignorer',`${settingsTabs()}<h3>Codes actuellement ignorés (${codes.length})</h3><p>Ces codes ne créent ni échantillon ni alerte. Les autres codes inconnus restent à examiner.</p><form id="pcr-ignored-form" data-revision="${c.revision}"><table aria-label="Codes actuellement ignorés"><thead><tr><th>Code SIL/middleware</th><th>État</th><th></th></tr></thead><tbody id="pcr-ignored-codes">${codes.map(ignoredRow).join('')}</tbody></table>${codes.length?'':'<p id="pcr-ignored-empty">Aucun code ignoré enregistré.</p>'}<p id="pcr-ignored-draft" class="form-error" hidden>Modifications en cours : enregistrez pour les appliquer.</p><div class="actions"><button type="button" data-action="pcr-add-ignored">Ajouter un code à ignorer</button><button class="primary">Enregistrer les codes ignorés</button></div></form><p class="muted">Pour reprendre un code ignoré : retirez-le de cette liste, ajoutez-le au catalogue, puis réincluez les dossiers concernés. Les messages restent disponibles pendant leur durée de conservation.</p>${reincludeButton()}`);
  }
  function receptionIssues(){const s=state.data.source;showModal('Connexion SIL/middleware · Messages à examiner',`${s.error?`<p class="form-error">${esc(s.error)}</p>`:''}<ul>${(s.issues||[]).map(i=>`<li>${esc(dateLabel(i.at))} · ${esc(displayText(i.error))}</li>`).join('')}</ul>${S.user.role==='admin'?'<div class="actions"><button data-action="pcr-codes">Codes et analyses</button><button data-action="pcr-ignored">Codes ignorés</button><button data-action="pcr-mca">Connexion SIL/middleware</button></div>':'<p>Signalez ce motif à un administrateur pour corriger le paramétrage ou la réception.</p>'}`);}
  function settingsTabs(){return '<div class="actions pcr-settings-tabs"><button data-action="pcr-codes">Codes et analyses</button><button data-action="pcr-ignored">Codes ignorés</button><button data-action="pcr-types">Types de PCR</button><button data-action="pcr-labs">Laboratoires et dossiers</button><button data-action="pcr-mca">Connexion SIL/middleware</button><button data-action="storage-settings">Sauvegarde</button></div>';}
  function labRow(family,r={prefix:'',barcode:'',label:''}){const reseau_c=family==='reseau_c';return `<tr class="pcr-lab-row"><td><input name="prefix" aria-label="${reseau_c?'Lettres du dossier':'Code du laboratoire'}" value="${esc(r.prefix)}" pattern="${reseau_c?'[A-Z]{1,2}':'[0-9]{2}'}" maxlength="2" required></td>${reseau_c?`<td><input name="barcode" aria-label="Préfixe du code-barres" value="${esc(r.barcode)}" inputmode="numeric" pattern="[0-9]{2}" maxlength="2" required></td>`:''}<td><input name="label" aria-label="Nom du laboratoire" value="${esc(r.label)}" maxlength="100" ${reseau_c?'':'required'}></td><td><input name="email" type="email" aria-label="Adresse mail du laboratoire" value="${esc(r.email||'')}" maxlength="254" placeholder="Pour les relances"></td><td><button type="button" data-action="pcr-remove-lab">Retirer</button></td></tr>`;}
  async function laboratories(){const c=await api('/pcr/config');state.labConfig=c;const n=c.numbering;showModal('Paramètres PCRLia · Laboratoires et dossiers',`${settingsTabs()}<form id="pcr-labs-form" data-revision="${c.revision}"><label class="checks"><input type="checkbox" name="enabled" ${n.enabled?'checked':''}>Retrouver les dossiers et les laboratoires à partir des codes-barres</label><p>Le suffixe de l’échantillon contient deux chiffres. Les zéros initiaux sont conservés. Un dossier transmis reste prioritaire.</p><div class="pcr-numbering-summary">Réseau A : dossier sur 8 chiffres · Réseau B : dossier sur 10 chiffres · Réseau C : préfixe à deux chiffres puis numéro du dossier.</div>${field('reseau_c_digits','Réseau C — nombre de chiffres après les lettres du dossier',n.reseau_c_digits,'number','required min="9" max="20"')}${['reseau_a','reseau_b','reseau_c'].map(f=>`<details class="pcr-lab-section" ${f==='reseau_a'?'open':''}><summary>${f==='reseau_a'?'Réseau A · chaque laboratoire apparaît séparément':({reseau_b:'Réseau B',reseau_c:'Réseau C'})[f]+' · un seul groupe dans les listes'}</summary><p>${f==='reseau_a'?'Deux premiers chiffres du dossier.':f==='reseau_b'?'Chiffres 6 et 7 du dossier. Le détail du site reste disponible au survol du code-barres.':'Remplacement des lettres par le préfixe du code-barres. Le détail du site reste disponible au survol du code-barres.'}</p><table class="pcr-lab-table"><thead><tr><th>${f==='reseau_c'?'Lettres':'Code'}</th>${f==='reseau_c'?'<th>Code-barres</th>':''}<th>Laboratoire</th><th>Mail de relance</th><th></th></tr></thead><tbody data-lab-family="${f}">${n[f].map(r=>labRow(f,r)).join('')}</tbody></table><button type="button" data-action="pcr-add-lab" data-family="${f}">Ajouter un laboratoire</button></details>`).join('')}<p class="muted">Exemples : 2900579788 → 29005797 · 611149537888 → 6111495378 · 1326111420488 → M261114204. Les correspondances restent modifiables ici.</p><button class="primary">Enregistrer les laboratoires</button></form>`);}
  function groupOptions(value){return state.data.groups.map(g=>`<option value="${g.id}" ${g.id===value?'selected':''}>${esc(g.label)}</option>`).join('');}
  function codeTable(items){return `<div class="pcr-code-list"><table class="pcr-code-table"><thead><tr><th>Technique</th><th>Analyse</th><th>Code SIL/middleware</th><th>Suffixe</th><th>Code « analyse faite »</th><th>Retard de réception</th>${alertOn('result')?'<th>Délai de résultat</th>':''}<th></th></tr></thead><tbody>${items.map(c=>`<tr data-code="${esc(c.code)}"><td>${esc(groupName(c.group_key))}</td><td><strong>${esc(c.label)}</strong></td><td>${esc(c.code)}</td><td class="pcr-barcode">${esc(c.suffix||'—')}</td><td>${esc(c.done_code||'—')}</td><td>${c.receipt_delay_hours?esc(c.receipt_delay_hours+' h'):'—'}</td>${alertOn('result')?`<td>${c.result_delay_hours?esc(c.result_delay_hours+' h'):'—'}</td>`:''}<td><button data-action="pcr-code-edit" data-code="${esc(c.code)}">Modifier</button></td></tr>`).join('')}</tbody></table></div>`;}
  function alertsForm(c){const a=c.delay_alerts||{receipt:true,result:false};return `<form id="pcr-alerts-form" class="pcr-alerts-form" data-revision="${c.revision}"><h3>Alertes de retard</h3><label class="checks"><input type="checkbox" name="receipt" ${a.receipt?'checked':''}><span><span class="pcr-late pcr-late-receipt">⧗ NON REÇU</span> Activer le retard de réception (tube attendu non scanné dans le délai)</span></label><label class="checks"><input type="checkbox" name="result" ${a.result?'checked':''}><span><span class="pcr-late pcr-late-result">⚗ SANS RÉSULTAT</span> Activer le retard de résultat (tube reçu sans résultat dans le délai)</span></label><p class="muted">Retard de réception désactivé : la pastille, la couleur de la ligne et le compteur « en retard » disparaissent. Retard de résultat désactivé : tout le suivi des résultats est masqué (rubrique « Suivi résultats » et délai de résultat). Les délais saisis par analyse sont conservés.</p>${closedFields(c.closed_days||{weekdays:[6],holidays_off:[],extra_dates:[]})}<button class="primary">Enregistrer les alertes</button></form>`;}
  function closedFields(cd){
    const year=new Date().getFullYear(),h=holidays(year),fr=iso=>iso.slice(8,10)+'/'+iso.slice(5,7)+'/'+iso.slice(0,4);
    return `<h3>Jours sans réception</h3><p class="muted">Ces jours ne comptent pas dans les délais : le compteur s’arrête puis reprend le jour suivant.</p><div class="pcr-closed-grid"><fieldset><legend>Jours de la semaine</legend>${WEEKDAYS.map((n,i)=>`<label class="checks"><input type="checkbox" name="closed_wd" value="${i}" ${cd.weekdays.includes(i)?'checked':''}>${n}</label>`).join('')}</fieldset><fieldset><legend>Jours fériés (dates ${year})</legend>${Object.entries(HOLIDAY_LABELS).map(([k,n])=>`<label class="checks"><input type="checkbox" name="closed_hol" value="${k}" ${cd.holidays_off.includes(k)?'':'checked'}>${n} <span class="muted">${fr(h[k])}</span></label>`).join('')}</fieldset></div><label>Fermetures exceptionnelles (une date par ligne, JJ/MM/AAAA)<textarea name="closed_extra" rows="3" placeholder="Ex. 26/12/2026">${esc(cd.extra_dates.map(fr).join('\n'))}</textarea></label>`;
  }
  function closedFromForm(f){
    const extra=f.elements.closed_extra.value.split(/\n+/).map(s=>s.trim()).filter(Boolean).map(s=>{const m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!m)throw new Error('Date de fermeture à corriger : '+s+' (format JJ/MM/AAAA).');return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;});
    return {weekdays:[...f.querySelectorAll('[name=closed_wd]:checked')].map(i=>Number(i.value)),holidays_off:[...f.querySelectorAll('[name=closed_hol]')].filter(i=>!i.checked).map(i=>i.value),extra_dates:extra};
  }
  async function codes(){state.data.codes=await api('/pcr/codes');const cfg=await api('/pcr/config');state.alertsConfig=cfg;const ordered=[...state.data.codes].sort((a,b)=>state.data.groups.findIndex(g=>g.id===a.group_key)-state.data.groups.findIndex(g=>g.id===b.group_key)||a.code.localeCompare(b.code)),active=ordered.filter(c=>c.active),inactive=ordered.filter(c=>!c.active);showModal('Paramètres PCRLia · Codes et analyses',`${settingsTabs()}${alertsForm(cfg)}${reincludeButton()}<p>Chaque code automate SIL/middleware correspond à une analyse et à un suffixe d’échantillon. Le code « analyse faite » est facultatif.</p>${active.length?codeTable(active):'<p>Aucune analyse active.</p>'}${inactive.length?`<details class="pcr-inactive-codes"><summary>Analyses désactivées (${inactive.length})</summary><p>Conservées pour lire les anciennes analyses et leur historique.</p>${codeTable(inactive)}</details>`:''}<h3>Ajouter une analyse</h3>${codeForm()}`);}
  function codeForm(c){return `<form id="pcr-code-form" class="account-form" data-revision="${c?.revision||0}" data-original-code="${esc(c?.code||'')}">${field('code','Code SIL/middleware',c?.code||'','text','required maxlength="80"')}${field('label','Analyse affichée',c?.label||'','text','required maxlength="160"')}<label>Technique<select name="group_key">${groupOptions(c?.group_key||'ist')}</select></label>${field('suffix','Suffixe échantillon',c?.suffix||'','text','required inputmode="numeric" pattern="[0-9]{2}" maxlength="2" placeholder="Ex. 88"')}${field('done_code','Code SIL/middleware « analyse faite » — facultatif',c?.done_code||'','text','maxlength="80" placeholder="Laisser vide si non utilisé"')}<p class="muted pcr-code-help">Facultatif. Quand le SIL/middleware envoie ce code pour un échantillon, la pastille de l’analyse passe au vert. Sans code, la pastille reste vide et rien d’autre ne change.</p><div class="grid2">${field('receipt_delay_hours','Retard de réception (heures) — facultatif',c?.receipt_delay_hours||'','number','min="1" max="2000" step="1" placeholder="Vide = pas d’alerte"')}${alertOn('result')?field('result_delay_hours','Délai de résultat après réception (heures) — facultatif',c?.result_delay_hours||'','number','min="1" max="2000" step="1" placeholder="Vide = pas d’alerte"'):''}</div><p class="muted pcr-code-help">Retard de réception : compté depuis la transmission de l’analyse par le SIL/middleware, tant que le tube n’est pas scanné.${alertOn('result')?' Délai de résultat : compté depuis le scan, tant que le SIL/middleware n’a pas signalé l’analyse faite (nécessite le code « analyse faite »).':''}</p>${c?'<p class="muted pcr-code-help">Si vous changez le code automate, l’ancien code sera désactivé. Les analyses déjà reçues et leur historique conserveront leur code d’origine.</p>':''}<label class="checks"><input type="checkbox" name="active" ${!c||c.active?'checked':''}>Analyse active</label><button class="primary">Enregistrer l’analyse</button>${c?`<button type="button" data-action="pcr-code-delete" data-code="${esc(c.code)}" data-revision="${c.revision}">Supprimer l’analyse</button><p class="muted">Une analyse déjà liée à des échantillons peut être désactivée ; son historique reste conservé.</p>`:''}</form>`;}
  function suffixRow(r={suffix:'',group:'ist',active:true}){return `<tr class="pcr-suffix-row"><td><input aria-label="Terminaison du tube" name="suffix" value="${esc(r.suffix)}" inputmode="numeric" pattern="[0-9]{2}" maxlength="2" required></td><td><select aria-label="Type de PCR" name="group">${groupOptions(r.group)}</select></td><td><input aria-label="Correspondance active" type="checkbox" name="active" ${r.active?'checked':''}></td><td><button type="button" data-action="pcr-remove-suffix">Retirer</button></td></tr>`;}
  async function types(){const c=await api('/pcr/config');showModal('Paramètres PCRLia · Types de PCR et dossiers',`${settingsTabs()}<form id="pcr-config-form" data-revision="${c.revision}"><h3>Classement par terminaison de tube</h3><p>Ces règles complètent les suffixes des analyses actives pour classer les tubes. Un suffixe reste reconnu si une analyse active l’utilise. Le pointage vérifie toujours le tube complet, le code automate et le suffixe prévu pour cette analyse.</p><table class="pcr-suffix-table"><thead><tr><th>Terminaison</th><th>Type de PCR</th><th>Active</th><th></th></tr></thead><tbody id="pcr-suffixes">${c.suffixes.map(suffixRow).join('')}</tbody></table><button type="button" data-action="pcr-add-suffix">Ajouter une correspondance</button><h3 class="pcr-config-title">Autres formats de dossier</h3><p>Les règles des réseaux A, B et C se règlent dans « Laboratoires et dossiers ». Pour les autres formats uniquement, reconstituer le dossier en retirant les derniers caractères du numéro d’échantillon. Un dossier transmis est toujours conservé.</p>${field('dossier_strip','Nombre de caractères à retirer à droite — 0 pour désactiver',c.dossier_strip,'number','required min="0" max="20"')}<p id="pcr-transcode-example" class="muted"></p><button class="primary">Enregistrer les correspondances</button></form>`);transcodeExample();}
  function transcodeExample(){const f=$('#pcr-config-form');if(!f)return;const n=Number(f.elements.dossier_strip.value),s='26000123486';$('#pcr-transcode-example').textContent=n===0?'Retrait générique désactivé. Les règles des laboratoires restent applicables.':n>0&&n<s.length?`Exemple : ${s} → ${s.slice(0,-n)}`:'Exemple trop court pour cette règle.';}
  function importForm(){state.preview=null;state.pending=null;showModal('Importer les analyses',`<p>Les analyses sont rapprochées par échantillon complet et code automate SIL/middleware. Les lignes absentes du fichier restent conservées.</p><form id="pcr-import-form"><label>Liste CSV (UTF-8, séparateur point-virgule)<input name="file" type="file" accept=".csv,text/csv" required></label>${field('source','Provenance de la liste','','text','required maxlength="160"')}<p class="muted">Le modèle comprend l’identifiant et le nom du patient. Le dossier peut rester vide. Paramétrer les analyses avant l’import.</p><div class="actions"><a class="button" href="/api/pcr/template.csv">Télécharger le modèle</a><button class="primary">Vérifier la liste</button></div></form>`);}
  async function preview(){const p=await api('/pcr/import-preview',state.pending);state.preview=p;showModal('Vérifier les analyses avant import',`<div class="banner info">${p.line_count} analyse(s) · ${p.sample_count} échantillon(s) · ${p.cancelled_orders} annulation(s).</div><p>Source : ${esc(p.source)}</p>${p.duplicate?'<p>Ce fichier a déjà été importé.</p>':''}${table(p.pairs,true)}<form id="pcr-import-confirm"><label class="checks"><input type="checkbox" name="confirmed" required>J’ai vérifié les analyses et leur provenance.</label><div class="actions"><button type="button" data-action="pcr-preview-refresh">Actualiser l’aperçu</button><button class="primary" ${p.duplicate?'disabled':''}>Confirmer l’import</button></div></form>`);}
  function click(a,el){if(!a.startsWith('pcr-'))return false;
    if(a==='pcr-tracking'){
      const p=state.data?.pairs.find(p=>p.sample_id===el.dataset.sample);
      if(p?.pending_issues?.length&&S.user.role!=='viewer'){
        state.confirming={sample_id:p.sample_id,revision:p.revision,duplicate_action:'',cancel_action:''};renderList();
        const row=document.querySelector(`.pcr-row[data-sample="${p.sample_id}"]`);
        const control=row?.querySelector('.pcr-duplicate-choice,.pcr-confirm-check');control?.focus({preventScroll:true});row?.scrollIntoView({block:'nearest'});
      }else run(()=>trackingDialog(el.dataset.sample));return true;
    }
    if(a==='pcr-home'||a==='pcr-filter'){const previous=state.filter;state.filter=a==='pcr-home'?'scan':el.dataset.filter;if(['errors','cancelled'].includes(state.filter))Object.assign(state,{search:'',site:'',from:'',to:'',group:'',patient:''});else if(['errors','cancelled','acks'].includes(previous))Object.assign(state,{from:defaultFrom(),to:''});render();return true;}
    if(a==='pcr-acks'){state.filter='acks';state.acking=null;Object.assign(state,{search:'',site:'',from:'',to:'',group:'',patient:''});render();return true;}
    if(a==='pcr-ack'){state.acking=el.dataset.key;renderList();document.querySelector('.pcr-ack-confirm')?.focus({preventScroll:true});return true;}
    if(a==='pcr-comment-edit'){state.editingComment=el.dataset.comment;commentsDialog(state.commentCtx.sid,state.commentCtx.code);$('.pcr-comment-edit-form textarea')?.focus();return true;}
    if(a==='pcr-comment-cancel'){state.editingComment=null;commentsDialog(state.commentCtx.sid,state.commentCtx.code);return true;}
    if(a==='pcr-comment-delete'){if(!confirm('Supprimer ce commentaire ?'))return true;run(async()=>{await api('/pcr/comment/change',{sample_id:el.dataset.sample,comment_id:el.dataset.comment,action:'delete'});await load();commentsDialog(state.commentCtx.sid,state.commentCtx.code);toast('Commentaire supprimé.');});return true;}
    if(a==='pcr-comment-toack'){run(async()=>{await api('/pcr/comment/change',{sample_id:el.dataset.sample,comment_id:el.dataset.comment,action:'to_ack'});await load();commentsDialog(state.commentCtx.sid,state.commentCtx.code);toast('Commentaire à acquitter.');});return true;}
    if(a==='pcr-comments'){state.editingComment=null;commentsDialog(el.dataset.sample,el.dataset.code||'');return true;}
    if(a==='pcr-mail-mode'){state.mailing=!state.mailing;if(!state.mailing)state.mailSel.clear();render();return true;}
    if(a==='pcr-mail-none'){state.mailSel.clear();renderList();return true;}
    if(a==='pcr-mail-late'){for(const p of filtered())if(['Réseau A','Réseau C','Réseau B'].includes(p.lab_family)&&receiptLate(p))state.mailSel.add(p.sample_id+'|'+p.request_code);renderList();return true;}
    if(a==='pcr-mail-prepare'){run(async()=>mailsDialog());return true;}
    if(a==='pcr-mail-open'){run(()=>openMails([Number(el.dataset.index)]));return true;}
    if(a==='pcr-mail-all'){run(()=>openMails(state.mails.map((_,i)=>i)));return true;}
    if(a==='pcr-mail-copy'){const m=state.mails[Number(el.dataset.index)];if(m){const text=m.body.split('\n\n')[2]||m.body;const copy=window.ClipboardItem?navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([m.htmlTable],{type:'text/html'}),'text/plain':new Blob([text],{type:'text/plain'})})]):navigator.clipboard.writeText(text);copy.then(()=>toast('Tableau copié : collez-le dans le brouillon (Ctrl+V).'),()=>toast('Copie impossible : sélectionner le tableau à la main.',true));}return true;}
    if(a==='pcr-all-dates'){state.from='';state.to='';render();return true;}
    if(a==='pcr-two-weeks'){state.from=defaultFrom();state.to='';render();return true;}
    if(a==='pcr-patient'){state.patient=el.dataset.patient;renderList();return true;}
    if(a==='pcr-clear-patient'){state.patient='';renderList();return true;}
    if(a==='pcr-print'){window.print();return true;}
    if(a==='pcr-import'){importForm();return true;}
    if(a==='pcr-code-edit'){const c=state.data.codes.find(c=>c.code===el.dataset.code);showModal('Modifier l’analyse',codeForm(c),true);return true;}
    if(a==='pcr-code-delete'){if(confirm('Supprimer cette analyse du paramétrage ? Les codes ainsi retirés seront ignorés à réception.'))run(async()=>{await api('/pcr/codes/delete',{code:el.dataset.code,revision:Number(el.dataset.revision)});await load();await codes();toast('Analyse supprimée.');});return true;}
    if(a==='pcr-reception-issues'){receptionIssues();return true;}
    if(a==='pcr-add-ignored'){$('#pcr-ignored-codes').insertAdjacentHTML('beforeend',ignoredRow());$('#pcr-ignored-draft').hidden=false;$('#pcr-ignored-empty')?.remove();$('#pcr-ignored-codes tr:last-child input').focus();return true;}
    if(a==='pcr-remove-ignored'){el.closest('tr').remove();$('#pcr-ignored-draft').hidden=false;return true;}
    if(a==='pcr-add-suffix'){$('#pcr-suffixes').insertAdjacentHTML('beforeend',suffixRow());return true;}
    if(a==='pcr-remove-suffix'){el.closest('tr').remove();return true;}
    if(a==='pcr-add-lab'){const family=el.dataset.family;$(`[data-lab-family="${family}"]`).insertAdjacentHTML('beforeend',labRow(family));return true;}
    if(a==='pcr-remove-lab'){el.closest('tr').remove();return true;}
    if(a==='pcr-dismiss-failure'){state.failed.splice(Number(el.dataset.index),1);$('#pcr-failed').innerHTML=failedView();return true;}
    if(a==='pcr-retry'){const job=state.failed.splice(Number(el.dataset.index),1)[0];if(job){state.queue.push(job);$('#pcr-failed').innerHTML=failedView();drain();}return true;}
    run(async()=>{if(a==='pcr-refresh')await load();else if(a==='pcr-mca')await mca();else if(a==='pcr-ignored')await ignoredCodes();else if(a==='pcr-mca-reinclude'){const r=await api('/pcr/mca/reinclude',{});await load();showModal('Réinclusion terminée',`<p>${countLabel(r.included_analyses,'nouvelle analyse intégrée','nouvelles analyses intégrées')} · ${countLabel(r.reexamined_messages,'message réexaminé','messages réexaminés')}.</p>${r.pending?`<p>${countLabel(r.pending,'message reste à examiner','messages restent à examiner')}.</p>`:''}${r.remaining_reinclude?`<p>${countLabel(r.remaining_reinclude,'message concerné reste à reprendre','messages concernés restent à reprendre')}.</p><button data-action="pcr-mca-reinclude">Réinclure les dossiers concernés</button>`:''}<p>Les analyses déjà présentes sont conservées sans doublon.</p>${settingsTabs()}`);}else if(a==='pcr-mca-retry'){await api('/pcr/mca/retry',{});await load();await mca();}else if(a==='pcr-codes'||a==='pcr-settings')await codes();else if(a==='pcr-types')await types();else if(a==='pcr-labs')await laboratories();else if(a==='pcr-preview-refresh')await preview();});return true;
  }
  async function submit(f,data){if(!f.id.startsWith('pcr-'))return false;
    if(f.id==='pcr-alerts-form'){await api('/pcr/config',{...state.alertsConfig,revision:Number(f.dataset.revision),delay_alerts:{receipt:f.elements.receipt.checked,result:f.elements.result.checked},closed_days:closedFromForm(f)});await load();await codes();toast('Alertes de retard enregistrées.');return true;}
    if(f.id==='pcr-comment-edit-form'){await api('/pcr/comment/change',{sample_id:f.dataset.sample,comment_id:f.dataset.comment,action:'edit',text:data.text});state.editingComment=null;await load();commentsDialog(state.commentCtx.sid,state.commentCtx.code);toast('Commentaire modifié.');return true;}
    if(f.id==='pcr-comment-form'){await api('/pcr/comment',{sample_id:f.dataset.sample,request_code:f.dataset.code,text:data.text,to_ack:data.to_ack==='on'});closeModal();await load();toast('Commentaire ajouté sur '+f.dataset.sample+'.');return true;}
    if(f.id==='pcr-mca-form'){await api('/pcr/mca',{enabled:data.enabled==='on',listen_address:data.listen_address.trim(),port:Number(data.port),mca_address:data.mca_address.trim(),encoding:data.encoding,raw_retention_days:Number(data.raw_retention_days)});await load();await mca();toast('Réception PCRLia enregistrée.');}

    if(f.id==='pcr-ignored-form'){const ignored_mca_codes=[...f.querySelectorAll('.pcr-ignore-row [name=code]')].map(el=>el.value.trim());await api('/pcr/config',{...state.ignoreConfig,revision:Number(f.dataset.revision),ignored_mca_codes});await load();await ignoredCodes();toast('Codes ignorés enregistrés.');}
    if(f.id==='pcr-labs-form'){const numbering={enabled:f.elements.enabled.checked,reseau_c_digits:Number(data.reseau_c_digits)};for(const family of ['reseau_a','reseau_b','reseau_c'])numbering[family]=[...f.querySelectorAll(`[data-lab-family="${family}"] .pcr-lab-row`)].map(row=>({prefix:row.querySelector('[name=prefix]').value,label:row.querySelector('[name=label]').value,...(family==='reseau_c'?{barcode:row.querySelector('[name=barcode]').value}:{}),email:row.querySelector('[name=email]').value.trim()}));await api('/pcr/config',{...state.labConfig,revision:Number(f.dataset.revision),numbering});await load();await laboratories();toast('Laboratoires enregistrés.');}
    if(f.id==='pcr-code-form'){await api('/pcr/codes',{...data,original_code:f.dataset.originalCode,active:data.active==='on',revision:Number(f.dataset.revision)});await load();await codes();toast('Analyse enregistrée.');}
    if(f.id==='pcr-config-form'){const suffixes=[...f.querySelectorAll('.pcr-suffix-row')].map(row=>({suffix:row.querySelector('[name=suffix]').value,group:row.querySelector('[name=group]').value,active:row.querySelector('[name=active]').checked}));await api('/pcr/config',{suffixes,dossier_strip:Number(data.dossier_strip),revision:Number(f.dataset.revision)});await load();await types();toast('Correspondances enregistrées.');}
    if(f.id==='pcr-import-form'){const file=f.elements.file.files[0];if(!file||file.size>2000000)throw new Error('Choisir un fichier CSV de 2 Mo maximum.');let content;try{content=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());}catch{throw new Error('Enregistrer le fichier au format UTF-8.');}state.pending={content,source:data.source};await preview();}
    if(f.id==='pcr-import-confirm'){await api('/pcr/import',{...state.pending,digest:state.preview.digest,revision:state.preview.revision,catalog_digest:state.preview.catalog_digest,confirmed:data.confirmed==='on'});state.preview=null;state.pending=null;closeModal();await load();toast('Dossiers importés.');}return true;
  }
  document.addEventListener('input',e=>{if(e.target.id==='pcr-search'){state.search=e.target.value;renderList();}if(e.target.name==='dossier_strip')transcodeExample();});
  document.addEventListener('change',e=>{const map={'pcr-site':'site','pcr-from':'from','pcr-to':'to','pcr-group':'group','pcr-order':'order'};if(map[e.target.id]){state[map[e.target.id]]=e.target.value;['pcr-from','pcr-to'].includes(e.target.id)?render():renderList();}});
  return {render,load,stop,reset,pendingScans,enqueue,click,submit};
})();
